import { http } from "../../platform/net/http.js";
class SceneUtils {
	static load(url, maxRetries, callback) {
		if (typeof url === "string") {
			url = {
				load: url,
				original: url
			};
		}
		http.get(url.load, {
			retry: maxRetries > 0,
			maxRetries
		}, (err, response) => {
			if (!err) {
				callback(err, response);
			} else {
				let errMsg = `Error while loading scene JSON ${url.original}`;
				if (err.message) {
					errMsg += `: ${err.message}`;
					if (err.stack) {
						errMsg += `
${err.stack}`;
					}
				} else {
					errMsg += `: ${err}`;
				}
				callback(errMsg);
			}
		});
	}
}
export {
	SceneUtils
};
